#!/usr/bin/env python3
"""V7.3 Arena V2 structured perception: Power + calibrated HP bars."""


def _replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label} expected one match, found {count}")
    return text.replace(old, new, 1)


def apply_arena_perception_core_patch(text):
    old = '''DEFAULT_OPPONENT_SETTINGS = {\n    "org_roi": None,\n    "username_roi": None,\n}\n'''
    new = '''DEFAULT_OPPONENT_SETTINGS = {\n    "org_roi": None,\n    "username_roi": None,\n    # V7.3 structured perception is calibration-based. Unknown/unset ROIs are\n    # never guessed and simply stay absent from the learning vector.\n    "power_roi": None,\n    "ally_hp_rois": [],\n    "enemy_hp_rois": [],\n    "move_roi": None,\n}\n'''
    text = _replace_once(text, old, new, "perception settings defaults")

    old = '''def opponent_username_roi():\n    roi = get_opponent_settings().get("username_roi")\n'''
    new = '''def _normalized_opponent_roi(value, min_w=12, min_h=8):\n    if not isinstance(value, (list, tuple)) or len(value) != 4:\n        return None\n    try:\n        x1, y1, x2, y2 = [int(round(float(v))) for v in value]\n    except Exception:\n        return None\n    x1 = max(0, min(REFERENCE_W - 1, x1))\n    y1 = max(0, min(REFERENCE_H - 1, y1))\n    x2 = max(x1 + 1, min(REFERENCE_W, x2))\n    y2 = max(y1 + 1, min(REFERENCE_H, y2))\n    if x2 - x1 < int(min_w) or y2 - y1 < int(min_h):\n        return None\n    return (x1, y1, x2, y2)\n\n\ndef opponent_power_roi():\n    return _normalized_opponent_roi(get_opponent_settings().get("power_roi"), 24, 10)\n\n\ndef opponent_move_roi():\n    roi = _normalized_opponent_roi(get_opponent_settings().get("move_roi"), 80, 60)\n    return roi if roi is not None else DODGE_ENEMY_ROI\n\n\ndef battle_hp_rois(side):\n    key = "ally_hp_rois" if str(side or "").lower().startswith("ally") else "enemy_hp_rois"\n    values = get_opponent_settings().get(key) or []\n    out = []\n    for value in values[:3]:\n        roi = _normalized_opponent_roi(value, 28, 5)\n        if roi is not None:\n            out.append(roi)\n    return out\n\n\ndef extract_power_value(text):\n    """Parse a calibrated Power/CP OCR result without inventing missing digits."""\n    candidates = []\n    for raw in re.findall(r"\\d[\\d\\s,._]*", str(text or "")):\n        digits = re.sub(r"\\D", "", raw)\n        if not digits:\n            continue\n        try:\n            value = int(digits)\n        except Exception:\n            continue\n        if 100 <= value <= 999_999_999:\n            candidates.append(value)\n    return max(candidates) if candidates else None\n\n\ndef read_opponent_power(ref_screen):\n    roi = opponent_power_roi()\n    if roi is None or not HAS_TESSERACT:\n        return None, None, ""\n    try:\n        region = crop(ref_screen, roi)\n        if region is None or region.size == 0:\n            return None, None, ""\n        prep = prep_ocr(region, scale=3.0)\n        data = pytesseract.image_to_data(\n            prep,\n            config="--psm 7 -c tessedit_char_whitelist=0123456789,._",\n            output_type=pytesseract.Output.DICT,\n        )\n        pieces, confs = [], []\n        for piece, conf in zip(data.get("text", []), data.get("conf", [])):\n            piece = str(piece or "").strip()\n            if not piece:\n                continue\n            try:\n                c = float(conf)\n            except Exception:\n                c = -1.0\n            if c >= 20:\n                pieces.append(piece)\n                confs.append(c)\n        raw = " ".join(pieces).strip()\n        value = extract_power_value(raw)\n        if value is None:\n            # One second OCR shape can recover stylized thousands separators.\n            fallback = pytesseract.image_to_string(\n                prep, config="--psm 7 -c tessedit_char_whitelist=0123456789,._"\n            )\n            raw = " ".join([raw, str(fallback or "").strip()]).strip()\n            value = extract_power_value(raw)\n        conf = (sum(confs) / len(confs)) if confs else None\n        return value, conf, raw[:80]\n    except Exception:\n        return None, None, ""\n\n\ndef _arena_bar_fill_ratio(ref_screen, roi):\n    """Estimate left-to-right bar fill inside a tightly calibrated HP rectangle."""\n    try:\n        region = crop(ref_screen, roi)\n        if region is None or region.size == 0:\n            return None\n        h, w = region.shape[:2]\n        if w < 20 or h < 4:\n            return None\n        # Ignore decorative border pixels and score saturated/lit bar pixels by column.\n        y1 = max(0, int(round(h * 0.20)))\n        y2 = min(h, max(y1 + 1, int(round(h * 0.80))))\n        hsv = cv2.cvtColor(region[y1:y2, :], cv2.COLOR_BGR2HSV)\n        sat = hsv[:, :, 1]\n        val = hsv[:, :, 2]\n        mask = ((sat >= 42) & (val >= 58)).astype(np.float32)\n        score = mask.mean(axis=0)\n        if score.size == 0:\n            return None\n        kernel_n = max(3, min(11, int(round(w / 28.0))))\n        kernel = np.ones(kernel_n, dtype=np.float32) / float(kernel_n)\n        smooth = np.convolve(score, kernel, mode="same")\n        peak = float(np.percentile(smooth, 90))\n        if peak < 0.10:\n            return 0.0\n        threshold = max(0.08, peak * 0.44)\n        active = smooth >= threshold\n        # Bar fill should begin on the left; ignore isolated late highlights by\n        # stopping after a sustained inactive gap once fill has begun.\n        started = False\n        last_active = -1\n        gap = 0\n        gap_limit = max(3, int(round(w * 0.05)))\n        for idx, flag in enumerate(active):\n            if flag:\n                started = True\n                last_active = idx\n                gap = 0\n            elif started:\n                gap += 1\n                if gap >= gap_limit:\n                    break\n        if last_active < 0:\n            return 0.0\n        return round(max(0.0, min(1.0, float(last_active + 1) / float(w))), 4)\n    except Exception:\n        return None\n\n\ndef _arena_hp_snapshot(ref_screen):\n    ally = [_arena_bar_fill_ratio(ref_screen, roi) for roi in battle_hp_rois("ally")]\n    enemy = [_arena_bar_fill_ratio(ref_screen, roi) for roi in battle_hp_rois("enemy")]\n    ally = [x for x in ally if x is not None]\n    enemy = [x for x in enemy if x is not None]\n    return {\n        "ally": ally,\n        "enemy": enemy,\n        "ally_avg": (sum(ally) / len(ally)) if ally else None,\n        "enemy_avg": (sum(enemy) / len(enemy)) if enemy else None,\n        "ally_alive": sum(1 for x in ally if x > 0.08),\n        "enemy_alive": sum(1 for x in enemy if x > 0.08),\n    }\n\n\ndef _arena_structured_battle_features(ref_screen):\n    snap = _arena_hp_snapshot(ref_screen)\n    ally = list(snap.get("ally") or [])[:3]\n    enemy = list(snap.get("enemy") or [])[:3]\n    ally += [-1.0] * (3 - len(ally))\n    enemy += [-1.0] * (3 - len(enemy))\n    ally_avg = snap.get("ally_avg")\n    enemy_avg = snap.get("enemy_avg")\n    diff = None if ally_avg is None or enemy_avg is None else ally_avg - enemy_avg\n    return [\n        *ally, *enemy,\n        float(ally_avg) if ally_avg is not None else -1.0,\n        float(enemy_avg) if enemy_avg is not None else -1.0,\n        float(diff) if diff is not None else -1.0,\n    ]\n\n\ndef _arena_catastrophic_state(ref_screen, learned_probability):\n    """Fast-loss accelerator requires BOTH calibrated HP evidence and learned risk."""\n    if learned_probability is None or float(learned_probability) < 0.88:\n        return False, ""\n    snap = _arena_hp_snapshot(ref_screen)\n    ally = snap.get("ally") or []\n    enemy = snap.get("enemy") or []\n    if len(ally) < 3 or len(enemy) < 3:\n        return False, ""\n    ally_avg = float(snap.get("ally_avg") or 0.0)\n    enemy_avg = float(snap.get("enemy_avg") or 0.0)\n    if (\n        ally_avg <= 0.14\n        and enemy_avg >= 0.50\n        and int(snap.get("ally_alive") or 0) <= 1\n        and int(snap.get("enemy_alive") or 0) >= 2\n    ):\n        return True, (\n            f"HP collapse ally={ally_avg:.0%}/{int(snap.get('ally_alive') or 0)} alive "\n            f"enemy={enemy_avg:.0%}/{int(snap.get('enemy_alive') or 0)} alive"\n        )\n    return False, ""\n\n\ndef opponent_username_roi():\n    roi = get_opponent_settings().get("username_roi")\n'''
    text = _replace_once(text, old, new, "structured perception helpers")

    old = '''        edges = cv2.Canny(gray, 70, 150)\n        edge_density = float(np.count_nonzero(edges)) / float(max(1, edges.size))\n        vec = np.concatenate([pooled.reshape(-1), hist, np.array([edge_density], dtype=np.float32)])\n        return [round(float(x), 5) for x in vec]\n'''
    new = '''        edges = cv2.Canny(gray, 70, 150)\n        edge_density = float(np.count_nonzero(edges)) / float(max(1, edges.size))\n        structured = np.array(_arena_structured_battle_features(ref_screen), dtype=np.float32)\n        vec = np.concatenate([\n            pooled.reshape(-1), hist,\n            np.array([edge_density], dtype=np.float32),\n            structured,\n        ])\n        return [round(float(x), 5) for x in vec]\n'''
    text = _replace_once(text, old, new, "structured learning vector")

    old = '''        probability, model_detail = arena_predict_loss(vec, elapsed, threat)\n\n        signature = _arena_frame_signature(ref_screen)\n'''
    new = '''        probability, model_detail = arena_predict_loss(vec, elapsed, threat)\n        catastrophic, catastrophic_detail = _arena_catastrophic_state(ref_screen, probability)\n        if catastrophic and probability is not None:\n            # Do not surrender from raw color alone. HP collapse only accelerates\n            # an already-learned high-loss state; normal confirmation still applies.\n            probability = max(float(probability), 0.975)\n            model_detail += f" • {catastrophic_detail}"\n\n        signature = _arena_frame_signature(ref_screen)\n'''
    text = _replace_once(text, old, new, "catastrophic learned-loss accelerator")

    marker = "\n# V7.3 Arena Structured Perception — calibrated Power + HP features build marker\n"
    if marker.strip() not in text:
        text += marker
    return text
